input.command:
cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and empty policy ---
  it.todo("quotes an empty item list -- premium 5 G (processing fee only)");

  // --- Quote: base premiums per main item type ---
  it.todo("quotes a single plain sword -- base 100 G + 10 G first insurance + 5 G fee = 115 G");
  it.todo("quotes a single plain amulet -- base 60 G + 6 G first insurance + 5 G fee = 71 G");
  it.todo("quotes a single plain staff -- base 80 G + 8 G first insurance + 5 G fee = 93 G");
  it.todo("quotes a single plain potion -- base 40 G + 4 G first insurance + 5 G fee = 49 G");

  // --- Quote: component base premiums and the building block ---
  it.todo("quotes a single rune -- base 25 G component premium");
  it.todo("quotes a single moonstone -- base 25 G component premium");
  it.todo("quotes 2 runes -- base premium 50 G (no block)");
  it.todo("quotes 3 runes -- base premium 60 G (block applies)");
  it.todo("quotes 4 runes -- base premium 100 G (no block: block requires exactly 3)");
  it.todo("quotes 7 runes -- base premium 175 G (no block: block requires exactly 3)");
  it.todo("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks)");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to the cursed item's base premium -- cursed sword 100 G -> 150 G");
  it.todo("adds a 30 % high-enchantment surcharge at enchantment exactly 5 -- sword 100 G -> 130 G");
  it.todo("adds no high-enchantment surcharge at enchantment 4 -- sword stays 100 G");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 -- 100 G -> 180 G");

  // --- Quote: modifier scope on multi-item policies ---
  it.todo("applies the curse surcharge only to the cursed item -- cursed sword + plain amulet -> 160 G base + 50 G = 210 G before further modifiers and fee");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies the 10 % first insurance surcharge to every item in a quote regardless of customer history");
  it.todo("applies the 20 % loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies a 15 % follow-up discount on each contract after the customer's first");
  it.todo("applies no follow-up discount to the customer's first contract");
  it.todo("adds the 5 G processing fee at the very end of every premium");

  // --- Quote: rounding in the MHPCO's favor ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favor)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years) -- premium 165 G");
  it.todo("quotes a long-standing customer's second contract: cursed sword enchantment 7, 3 years -- premium 160 G");

  // --- Quote: rejection ---
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick) -- CLI exits non-zero, error on stderr, no results on stdout");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a single-sword policy at 2000 G (twice the 1000 G insurance sum)");
  it.todo("sums insurance values across items -- sword + amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("bases the cap on unmodified insurance values -- cursed sword (premium 165 G) -> cap 2000 G");
  it.todo("counts component insurance values at 250 G each -- sword + 3 runes -> insurance sum 1750 G (block affects premium only)");
  it.todo("counts two swords as insurance sum 2000 G, cap 4000 G");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("reimburses a regular steel sword (enchantment 3) damage of 500 G -- payout 400 G");
  it.todo("reimburses a rune damage of 200 G -- payout 100 G (no enchantment or material clause)");
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G -> payout 600 G");
  it.todo("treats each damages entry of the same item type as a separate damage with its own deductible -- two damaged swords");

  // --- Claim: special clauses ---
  it.todo("reimburses damage to an item with enchantment exactly 8 at 50 % -- dragon sword, damage 1000 G -> payout 400 G");
  it.todo("reimburses dragon-material damage fully -- dragon sword enchantment 5, damage 800 G -> payout 700 G");
  it.todo("lets the 50 % high-enchantment rule win over full dragon reimbursement -- dragon sword enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("applies the high-enchantment clause alone to a steel sword enchantment 9, damage 1000 G -> payout 400 G");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("pays 1400 G on a first 1500 G claim against a 2000 G cap -- remainingCap 600 G");
  it.todo("reduces a second 1500 G claim to the remaining cap -- payout 600 G, remainingCap 0 G");

  // --- Claim: rounding in the MHPCO's favor ---
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favor)");

  // --- Claim: rejection ---
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) -- CLI exits non-zero with stderr error");
  it.todo("rejects a claim referencing an unknown item type -- CLI exits non-zero with stderr error");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -- CLI exits non-zero with stderr error");
  it.todo("rejects a claim with a negative damage amount (-200) -- CLI exits non-zero with stderr error");

  // --- CLI: scenario orchestration and JSON contract ---
  it.todo("reads a scenario from stdin and writes {results:[...]} to stdout in step order");
  it.todo("resolves a claim step's policy field to the zero-based index of the earlier quote step");
  it.todo("returns premium for quote results and payout + remainingCap for claim results");
});
