export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BASE_PREMIUM = 25;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const PROCESSING_FEE = 5;

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.has(item.type);
}

function basePremiumFor(item: Item): number {
  return isComponent(item)
    ? COMPONENT_BASE_PREMIUM
    : MAIN_ITEM_BASE_PREMIUMS[item.type];
}

function policyBasePremiumFor(items: Item[]): number {
  return items.reduce((total, item) => total + basePremiumFor(item), 0);
}

function roundInMHPCOsFavour(premium: number): number {
  return Math.ceil(premium);
}

export function quote(customer: Customer, items: Item[]): number {
  const basePremium = policyBasePremiumFor(items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  const premium = basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
  return roundInMHPCOsFavour(premium);
}
