export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const PROCESSING_FEE = 5;

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.has(item.type);
}

function isMainItem(item: Item): boolean {
  return !isComponent(item);
}

function mainItemBasePremium(item: Item): number {
  return MAIN_ITEM_BASE_PREMIUMS[item.type];
}

function alikeGroupBasePremium(count: number): number {
  return count === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : count * COMPONENT_BASE_PREMIUM;
}

/** Components are "alike" when they are of exactly the same type. */
function alikeKey(component: Item): string {
  return component.type;
}

function componentsBasePremium(components: Item[]): number {
  const countsPerAlikeGroup = new Map<string, number>();
  for (const component of components) {
    const key = alikeKey(component);
    countsPerAlikeGroup.set(key, (countsPerAlikeGroup.get(key) ?? 0) + 1);
  }
  return [...countsPerAlikeGroup.values()].reduce(
    (total, count) => total + alikeGroupBasePremium(count),
    0,
  );
}

function mainItemsBasePremium(mainItems: Item[]): number {
  return mainItems.reduce((total, item) => total + mainItemBasePremium(item), 0);
}

function policyBasePremiumFor(items: Item[]): number {
  return (
    mainItemsBasePremium(items.filter(isMainItem)) +
    componentsBasePremium(items.filter(isComponent))
  );
}

function roundInMHPCOsFavour(premium: number): number {
  return Math.ceil(premium);
}

/**
 * Policy-wide modifiers apply to the policy base premium (the sum of all item
 * base premiums) and are added to it, never multiplied onto it.
 */
function policyWideModifiers(policyBasePremium: number): number {
  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
}

export function quote(customer: Customer, items: Item[]): number {
  const policyBasePremium = policyBasePremiumFor(items);
  const premium =
    policyBasePremium + policyWideModifiers(policyBasePremium) + PROCESSING_FEE;
  return roundInMHPCOsFavour(premium);
}
