/** Rounded in MHPCO's favour: a payout of 350.5 G is settled at 350 G. */
function roundPayoutInMHPCOsFavour(payout: number): number {
  return Math.floor(payout);
}

/**
 * What one damage earns after the office's excess: the deductible falls on the
 * damage event, so every entry in an incident bears it separately — two damaged
 * items, two deductibles.
 */
function damageNetOfDeductible(damage: Damage): number {
  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
}

/** What the incident earns on its own merits, cap not yet applied. */
function reimbursementForIncident(incident: Incident): number {
  return incident.damages.reduce(
    (total, damage) => total + damageNetOfDeductible(damage),
    0,
  );
}

/**
 * The settlement: what MHPCO actually pays. The office never pays more than
 * the cap still available on the policy, however much the damage earns.
 */
function settlementFor(policy: Policy, incident: Incident): number {
  return roundPayoutInMHPCOsFavour(
    Math.min(reimbursementForIncident(incident), policy.remainingCap),
  );
}

/** Settling a claim pays the settlement and draws it down from the policy's cap. */
export function claim(policy: Policy, incident: Incident): ClaimResult {
  const payout = settlementFor(policy, incident);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}

