cat > src/cli.ts <<'EOF'
import {
  claim,
  createPolicy,
  quote,
  type Customer,
  type Incident,
  type Item,
  type Policy,
} from "./claim-office.js";

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

type Step = QuoteStep | ClaimStep;

interface Scenario {
  customer: Customer;
  steps: Step[];
}

type StepResult = { premium: number } | { payout: number; remainingCap: number };

/** The policy a claim step reports against, named by the quote step that wrote it. */
function policyWrittenBy(policies: Map<number, Policy>, index: number): Policy {
  const policy = policies.get(index);
  if (policy === undefined) {
    throw new Error(`step ${index} did not write a policy`);
  }
  return policy;
}

/**
 * Works the scenario's steps in order: a quote prices a contract and writes the
 * policy the later claim steps report against, and each quote after the first
 * is a follow-up contract for the customer.
 */
function resultsFor(scenario: Scenario): StepResult[] {
  const policies = new Map<number, Policy>();
  return scenario.steps.map((step, index) => {
    if (step.op === "quote") {
      const customer = {
        ...scenario.customer,
        previousContracts: policies.size,
      };
      const premium = quote(customer, step.items);
      policies.set(index, createPolicy(step.items));
      return { premium };
    }
    return claim(policyWrittenBy(policies, step.policy), step.incident);
  });
}

function readStdin(): string {
  return require("node:fs").readFileSync(0, "utf8");
}

function main(): void {
  const scenario = JSON.parse(readStdin()) as Scenario;
  process.stdout.write(JSON.stringify({ results: resultsFor(scenario) }));
}

try {
  main();
} catch (error) {
  process.stderr.write(`${(error as Error).message}\n`);
  process.exit(1);
}
EOF
